from collections import Counter, defaultdict, deque

def _shape(points):
    ys = [y for y, x in points]
    xs = [x for y, x in points]
    base = [(y-min(ys), x-min(xs)) for y, x in points]
    variants = []
    for fy in (1, -1):
        for k in range(4):
            q = []
            for y, x in base:
                y, x = y, x*fy
                for _ in range(k):
                    y, x = x, -y
                q.append((y, x))
            my = min(y for y, x in q); mx = min(x for y, x in q)
            variants.append(tuple(sorted((y-my, x-mx) for y, x in q)))
    return min(variants)

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            seen.add((r, c)); q = deque([(r, c)]); pts = []
            while q:
                y, x = q.popleft(); pts.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx)); q.append((ny, nx))
            comps.append((color, pts))

    marker = None
    for color, pts in comps:
        y0=min(y for y,x in pts); y1=max(y for y,x in pts)
        x0=min(x for y,x in pts); x1=max(x for y,x in pts)
        hh=y1-y0+1; ww=x1-x0+1
        if hh < 4 or ww < 4 or len(pts) != hh+ww-1:
            continue
        s=set(pts)
        valid = (
            (all((y,x0) in s for y in range(y0,y1+1)) and all((y0,x) in s for x in range(x0,x1+1))) or
            (all((y,x1) in s for y in range(y0,y1+1)) and all((y0,x) in s for x in range(x0,x1+1))) or
            (all((y,x0) in s for y in range(y0,y1+1)) and all((y1,x) in s for x in range(x0,x1+1))) or
            (all((y,x1) in s for y in range(y0,y1+1)) and all((y1,x) in s for x in range(x0,x1+1)))
        )
        if valid:
            marker=(color,pts); break
    if marker is None:
        return [row[:] for row in grid]
    mark_color, mark_pts = marker

    # The matching small sample is a two-cell vertical domino; recolor its
    # other occurrence to the large marker color.
    vertical=[]
    for color, pts in comps:
        if color == mark_color or len(pts) != 2:
            continue
        if pts[0][1] == pts[1][1] and abs(pts[0][0]-pts[1][0]) == 1:
            vertical.append((color, pts))
    groups=defaultdict(list)
    for color, pts in vertical:
        groups[_shape(pts)].append((color,pts))
    copies=next((items for items in groups.values() if len(items)>=2), None)
    if not copies:
        return [row[:] for row in grid]
    target=copies[-1][1]
    out=[row[:] for row in grid]
    for y,x in target:
        out[y][x]=mark_color
    return out

